INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(45011, 'Judges 11:7', 'Judges', 11, 7, 'خو یفتاح په ځواب کې وویل: «تاسو زما څخه دومره کرکه کوله چې زه مو د خپل پلار د کور پرېښودلو ته مجبور کړم. اوس چې په تاسو باندې تکلیف راغلی دی، نو ماته راغلئ؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges11_verse_7.mp3', '', 1761754199, 1761754199),
(45012, 'Judges 11:8', 'Judges', 11, 8, 'مشرانو وویل: «خو مونږ اوس ستا څخه غواړو چې بېرته راشې. که چېرې د عمونیانو سره په جنګ کې زمونږ مشري وکړې، نو مونږ به تا د جلعاد د ټولو خلکو مشر کړو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges11_verse_8.mp3', '', 1761754199, 1761754199),
(45013, 'Judges 11:9', 'Judges', 11, 9, 'یفتاح په ځواب کې وویل: «که چېرې تاسو ما د عمونیانو سره د جګړې دپاره بوځئ او څښتن هغوی ماته په لاس راکړي، ایا زه به په رښتیا ستاسو مشر شم؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges11_verse_9.mp3', '', 1761754199, 1761754199),
(45014, 'Judges 11:10', 'Judges', 11, 10, 'د جلعاد مشرانو یفتاح ته په ځواب کې وویل: «څښتن به زمونږ ترمنځ شاهد وي. مونږ وعده کوو څه چې ته وایې هماغسې به کوو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges11_verse_10.mp3', '', 1761754199, 1761754199),
(45015, 'Judges 11:11', 'Judges', 11, 11, 'نو یفتاح د جلعاد د مشرانو سره لاړ او خلکو هغه خپل مشر او قوماندان وټاکه. کومې خبرې چې یفتاح مشرانو ته کړې وې، هغه یې په مصفه کې د څښتن په حضور کې تکرار کړلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges11_verse_11.mp3', '', 1761754199, 1761754199),
(45016, 'Judges 11:12', 'Judges', 11, 12, 'بیا یفتاح د عمون پاچا ته استازي ورولېږل چې هغه ته ووایي: «ته زمونږ سره څه دښمني لرې؟ تا ولې زمونږ په هېواد باندې حمله کړې ده؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges11_verse_12.mp3', '', 1761754199, 1761754199),
(45017, 'Judges 11:13', 'Judges', 11, 13, 'د عمون پاچا د یفتاح استازو ته په ځواب کې وویل: «کله چې اسراییلیان د مصر څخه ووتل، هغوی زما ځمکه د ارنون د سیند څخه نیولې د یبوق او د اردن د سیندونو پورې ونیوله. اوس په سوله اییز ډول هغه ماته بېرته راکړه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges11_verse_13.mp3', '', 1761754199, 1761754199),
(45018, 'Judges 11:14', 'Judges', 11, 14, 'یفتاح بېرته د عمون پاچا ته استازي ورولېږل', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges11_verse_14.mp3', '', 1761754199, 1761754199),
(45019, 'Judges 11:15', 'Judges', 11, 15, 'چې هغه ته ووایي: «دا خبره رښتیا نه ده چې اسراییلو د موآبیانو او عمونیانو ځمکه نیولې وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges11_verse_15.mp3', '', 1761754199, 1761754199),
(45020, 'Judges 11:16', 'Judges', 11, 16, 'بلکې کله چې اسراییلیان د مصر څخه ووتل، هغوی د دښتې په لاره باندې سرې بحیرې ته او بیا قادش ته لاړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges11_verse_16.mp3', '', 1761754199, 1761754199),
(45021, 'Judges 11:17', 'Judges', 11, 17, 'بیا هغوی د ادوم پاچا ته استازي ولېږل چې د هغه څخه د هغه د هېواد څخه د تېرېدلو دپاره اجازه واخلي، خو د ادوم پاچا هغوی ته اجازه ورنه کړه. هغوی د موآب د پاچا څخه هم دا غوښتنه وکړه، خو هغه هم اجازه ورنه کړه چې د هغوی په هېواد باندې تېر شي. نو اسراییلیان په قادش کې پاتې شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges11_verse_17.mp3', '', 1761754199, 1761754199),
(45022, 'Judges 11:18', 'Judges', 11, 18, 'بیا هغوی د دښتې په لاره لاړل او د ادوم او د موآب په هېوادونو باندې راتاو شول او د موآب ختیځ خواته راغلل. د ارنون د سیند په بله غاړه باندې یې خېمې ودرولې، خو د ارنون د سیند څخه تېر نه شول، ځکه چې هغه د موآب سرحد ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges11_verse_18.mp3', '', 1761754199, 1761754199),
(45023, 'Judges 11:19', 'Judges', 11, 19, 'بیا اسراییلیانو سیحون د اموریانو پاچا ته چې پایتخت یې په حشبون کې ؤ، استازي ولېږل او د هغه څخه یې اجازه وغوښتله چې د هغوی د خاورې په لاره باندې خپل هېواد ته لاړ شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges11_verse_19.mp3', '', 1761754199, 1761754199),
(45024, 'Judges 11:20', 'Judges', 11, 20, 'خو سیحون په اسراییلیانو باندې اعتبار ونه کړ چې د هغه د سیمې له لارې تېر شي. هغه خپل ټول کسان راټول کړل او په یاهص کې یې خېمې ودرولې او په اسراییلیانو باندې یې حمله وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges11_verse_20.mp3', '', 1761754199, 1761754199),
(45025, 'Judges 11:21', 'Judges', 11, 21, 'خو د اسراییلو څښتن خدای اسراییلیان په سیحون او د هغه په لښکر باندې بریالي کړل. نو اسراییلیانو د هغو اموریانو ټوله سیمه چې هغوی په کې اوسېدل، ونیوله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges11_verse_21.mp3', '', 1761754199, 1761754199),
(45026, 'Judges 11:22', 'Judges', 11, 22, 'هغوی د اموریانو ټوله سیمه د ارنون د سیند څخه د یبوق تر سیند پورې او د دښتې څخه د اردن تر سیند پورې ونیوله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges11_verse_22.mp3', '', 1761754199, 1761754199),
(45027, 'Judges 11:23', 'Judges', 11, 23, 'نو دا د اسراییلو څښتن خدای ؤ چې د خپل قوم یعنې اسراییلو په خاطر یې اموریان وشړل. ایا تاسو د دې هڅه کوئ چې هغه بېرته واخلئ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges11_verse_23.mp3', '', 1761754199, 1761754199),
(45028, 'Judges 11:24', 'Judges', 11, 24, 'هرڅه چې تاسو ته ستاسو خدای کموش درکړي دي، هغه تاسو خپلو ځانونو ته وساتئ، خو هرڅه چې زمونږ څښتن خدای مونږ ته راکړي دي، هغه به مونږ خپلو ځانونو ته وساتو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges11_verse_24.mp3', '', 1761754199, 1761754199),
(45029, 'Judges 11:25', 'Judges', 11, 25, 'ایا ته د صفور د زوی بالاق څخه چې د موآب پاچا ؤ، ډېر ښه یې؟ ایا هغه کله د اسراییلو سره کومه دعوه کړې ده، یا یې د هغوی سره جګړه کړې ده؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges11_verse_25.mp3', '', 1761754199, 1761754199),
(45030, 'Judges 11:26', 'Judges', 11, 26, 'درې سوه کاله کیږي چې اسراییلیان په حشبون، عروعیر او د هغو شاوخوا کلیو او هغو ټولو ښارګوټو کې چې د ارنون د سیند په غاړه پراته دي، اوسیږي. تاسو په هغه وخت کې ولې هغه بېرته ونه نیول؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges11_verse_26.mp3', '', 1761754199, 1761754199),
(45031, 'Judges 11:27', 'Judges', 11, 27, 'ما ستا سره څه بدي نه ده کړې، بلکې ته زما سره بدي کوې او راغلی یې چې جګړه راسره وکړې. څښتن چې قاضي دی، پرېږده چې هغه نن د اسراییلیانو او عمونیانو ترمنځ پرېکړه وکړي چې زمونږ څخه کوم یو په حقه دی، اسراییل یا عمون.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges11_verse_27.mp3', '', 1761754199, 1761754199),
(45032, 'Judges 11:28', 'Judges', 11, 28, 'خو د عمون پاچا د یفتاح پیغام ته هېڅ پام ونه کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges11_verse_28.mp3', '', 1761754199, 1761754199),
(45033, 'Judges 11:29', 'Judges', 11, 29, 'بیا په یفتاح باندې د څښتن روح نازل شو. څنګه چې هغه د جلعاد او منسي څخه تېر شو، یو لښکر یې تیار کړ او د جلعاد مصفې ته راستون شو او د هغه ځای څخه عمون ته لاړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges11_verse_29.mp3', '', 1761754199, 1761754199),
(45034, 'Judges 11:30', 'Judges', 11, 30, 'یفتاح د څښتن سره قسم وخوړ او ویې ویل: «که چېرې عمونیان ماته په لاس راکړې،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges11_verse_30.mp3', '', 1761754199, 1761754199),
(45035, 'Judges 11:31', 'Judges', 11, 31, 'نو کله چې زه په بریالیتوب سره راستون شم، نو لومړنی کس چې زما د کور څخه به زما لیدلو ته راووځي، هغه به د څښتن وي او زه به هغه د سوځېدونکې نذارنې په توګه قرباني کړم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges11_verse_31.mp3', '', 1761754199, 1761754199),
(45036, 'Judges 11:32', 'Judges', 11, 32, 'نو یفتاح د سیند څخه تېر شو او د عمونیانو سره یې جګړه وکړه او څښتن هغه ته بری ورکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges11_verse_32.mp3', '', 1761754199, 1761754199),
(45037, 'Judges 11:33', 'Judges', 11, 33, 'هغه د عروعیر څخه د منیت د شاوخوا سیمې پورې او د ابیل کرامیم پورې شل ښارګوټي له منځه یووړل. په هغه ځای کې زیاته وژنه وشوه او عمونیانو د اسراییلو له خوا ماتې وخوړله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges11_verse_33.mp3', '', 1761754199, 1761754199),
(45038, 'Judges 11:34', 'Judges', 11, 34, 'کله چې یفتاح خپل کور ته چې په مصفه کې ؤ راستون شو، هغه کس چې د هغه مخې ته ورغی د هغه لور وه، هغې نڅا کوله او چمبه یې وهله. دا د هغه یوازېنی اولاد ؤ. له هغې پرته هغه نه زوی درلود او نه لور.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges11_verse_34.mp3', '', 1761754199, 1761754199),
(45039, 'Judges 11:35', 'Judges', 11, 35, 'کله چې هغه خپله لور ولیدله، نو د غمه یې خپل کالي وشکول او چیغې یې کړې: «ای زما لورې! تا زما زړه مات کړ! ولې دې زه ودردولم؟ ما څښتن ته نذر منلی دی او زه نه شم کولای چې د هغه څخه وګرځم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges11_verse_35.mp3', '', 1761754199, 1761754199),
(45040, 'Judges 11:36', 'Judges', 11, 36, 'هغې ورته وویل: «که چېرې تا د څښتن سره وعده کړې وي، نو څنګه چې دې ویلي دي هماغسې کار راسره وکړه، ځکه چې څښتن ستا د دښمنانو یعنې عمونیانو څخه ستا بدله واخیستله.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges11_verse_36.mp3', '', 1761754199, 1761754199),
(45041, 'Judges 11:37', 'Judges', 11, 37, 'خو هغې د خپل پلار څخه دا غوښتنه وکړه: «زما دپاره یو کار وکړه. ما د دوو میاشتو دپاره پرېږده چې د خپلو ملګرو سره په غرونو کې وګرځم او هلته ویر وکړم، ځکه چې زه به په پېغلتوب کې مړه شم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges11_verse_37.mp3', '', 1761754199, 1761754199),
(45042, 'Judges 11:38', 'Judges', 11, 38, 'هغه وویل: «لاړه شه» او هغه یې پرېښودله چې د دوو میاشتو دپاره لاړه شي. هغه د نجونو سره غرونو ته لاړه او ویې ژړل، ځکه چې هغه به ناواده شوې او بې اولاده مړه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges11_verse_38.mp3', '', 1761754199, 1761754199),
(45043, 'Judges 11:39', 'Judges', 11, 39, 'دوه میاشتې وروسته هغه بېرته خپل پلار ته راغله او د هغې پلار چې څښتن ته کوم نذر منلی ؤ هغه یې پوره کړ او هغه پېغله وه چې مړه شوه. له دې وروسته دا په اسراییلو کې یو رواج شو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges11_verse_39.mp3', '', 1761754199, 1761754199),
(45044, 'Judges 11:40', 'Judges', 11, 40, 'چې هر کال به د اسراییلو پېغلې د څلورو ورځو دپاره وتلې او د جلعادي یفتاح د لور دپاره به یې ویر کاوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges11_verse_40.mp3', '', 1761754199, 1761754199),
(45045, 'Isaiah 31:1', 'Isaiah', 31, 1, 'افسوس د هغو کسانو په حال چې د مصر د خلکو څخه مرسته غواړي! هغوی د مصر په لوی نظامي قوت، یعنې اسونو، جنګي ګاډیو او په اسونو سپاره عسکرو باندې تکیه کوي. خو هغوی په څښتن، یعنې د اسراییلو په سپېڅلي خدای تکیه نه کوي او نه ورڅخه مشوره غواړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah31_verse_1.mp3', '', 1761754199, 1761754199),
(45046, 'Isaiah 31:2', 'Isaiah', 31, 2, 'خو څښتن په خپل حکمت سره پوهیږي چې څه بلا او مصیبت په هغوی نازل کړي. هغه خپله اراده سرته رسوي. بد عمله خلکو او د هغوی ملاتړ کوونکو ته به سزا ورکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah31_verse_2.mp3', '', 1761754199, 1761754199),
(45047, 'Isaiah 31:3', 'Isaiah', 31, 3, 'مصریان انسانان دي، نه خدای. د هغوی اسونه یوازې جسم لري، کوم روحاني موجودات نه دي. کله چې څښتن هغوی ته د سزا ورکولو دپاره خپل لاس اوږد کړي، نو مرسته ورکوونکي به وښوییږي او مرسته اخیستونکي به ولویږي. ټول به یوځای له منځه لاړ شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah31_verse_3.mp3', '', 1761754199, 1761754199),
(45048, 'Isaiah 31:4', 'Isaiah', 31, 4, 'څښتن ماته داسې وویل: «فرض کړئ یو زمری په خپل ښکار باندې غوریږي او د شپنو یوه ډله راغونډیږي چې ویې شړي، خو بیاهم زمری په بې پروایۍ سره د شپنو د چیغو او شورماشور څخه نه وېریږي. همدا شان به زه چې مطلق قادر څښتن یم، د صهیون په غره د جګړې دپاره راښکته شم. زما مخه هېڅوک نه شي نیولی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah31_verse_4.mp3', '', 1761754199, 1761754199),
(45049, 'Isaiah 31:5', 'Isaiah', 31, 5, 'لکه څنکه چې یوه مرغۍ د خپلو بچیانو د ساتلو دپاره د خپلې ځالې په شاوخوا کې الوزي، نو زه مطلق قادر څښتن به هم د اورشلیم ساتنه کوم او هغه به وژغورم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah31_verse_5.mp3', '', 1761754199, 1761754199),
(45050, 'Isaiah 31:6', 'Isaiah', 31, 6, 'ای د اسراییلو خلکو، تاسو د څښتن په وړاندې سخته سرغړونه کړې ده. نو اوس بېرته د هغه خواته راوګرځئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah31_verse_6.mp3', '', 1761754199, 1761754199),
(45051, 'Isaiah 31:7', 'Isaiah', 31, 7, 'یو داسې وخت راروان دی چې تاسو ټول به هغه بتان چې په خپلو ګناهکارو لاسونو مو له سپینو او سرو زرو جوړ کړي دي، لېرې وغورځوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah31_verse_7.mp3', '', 1761754199, 1761754199),
(45052, 'Isaiah 31:8', 'Isaiah', 31, 8, '«اشوریان به د تورې په وسیله له منځه لاړ شي، خو نه د انسان په توره. هغوی به د جګړې له ډګره وتښتي او ځوانان به یې د بېګارۍ دپاره ونیول شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah31_verse_8.mp3', '', 1761754199, 1761754199),
(45053, 'Isaiah 31:9', 'Isaiah', 31, 9, 'د هغوی زړور عسکر به له وېرې وتښتي او د هغوی قوماندانان به دومره ووېریږي چې هغوی به خپل د جګړې بیرغونه هم پرېږدي او وبه تښتي.» دا د څښتن وینا ده، هغه څښتن چې حضور یې په صهیون کې د اور او په اورشلیم کې د تنور په شان دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah31_verse_9.mp3', '', 1761754199, 1761754199),
(45054, 'Isaiah 1:1', 'Isaiah', 1, 1, 'په دې کتاب کې هغه رویا ده چې خدای د یهودا او اورشلیم په اړه د عزیا، یوتام، احاز او حزقیا د پاچاهۍ په دوران کې د آموص زوی اشعیا ته ښکاره کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah1_verse_1.mp3', '', 1761754199, 1761754199),
(45055, 'Isaiah 1:2', 'Isaiah', 1, 2, 'څښتن وویل: «ای اسمانه او ځمکې، زه چې څه وایم ورته غوږ ونیسئ! کوم اولادونه چې ما وروزل او لوی مې کړل، هغوی زما په وړاندې سرغړونه وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah1_verse_2.mp3', '', 1761754199, 1761754199),
(45056, 'Isaiah 1:3', 'Isaiah', 1, 3, 'غویان خپل خاوند او خره خپل اخور پېژني چې څوک ورته خوراک رسوي. خو زما قوم اسراییل ما نه پېژني، ځکه چې شعور نه لري.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah1_verse_3.mp3', '', 1761754199, 1761754199),
(45057, 'Isaiah 1:4', 'Isaiah', 1, 4, 'ای د ګناهونو نه ډک، فاسد او بدعمله قومه! تاسو په خپلو ګناهونو کې ډوب شوي یئ! تاسو څښتن د اسراییلو سپېڅلی خدای پریښی، د هغه نه مو مخ اړولی او سپکاوی مو ورته کړی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah1_verse_4.mp3', '', 1761754199, 1761754199),
(45058, 'Isaiah 1:5', 'Isaiah', 1, 5, 'تاسو ولې خپل یاغیتوب ته دوام ورکوئ؟ ایا غواړئ چې د دې نه نوره هم زیاته سزا ووینئ؟ ستاسو سر ټپي او زړه مو ناروغ دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah1_verse_5.mp3', '', 1761754199, 1761754199),
(45059, 'Isaiah 1:6', 'Isaiah', 1, 6, 'له سره نیولې تر پښو ستاسو په بدن کې روغ ځای نشته. ستاسو ټول بدن ټپي، موړې موړې او د ناسور په زخم بدل شوی دی. ستاسو زخمونه لا پاک شوي نه دي، نه ورباندې پټۍ ایښودل کیږي او نه هم ملهم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah1_verse_6.mp3', '', 1761754199, 1761754199),
(45060, 'Isaiah 1:7', 'Isaiah', 1, 7, 'ستاسو وطن وران شوی او ښارونه مو سوځول شوي دي. ستاسو د سترګو په وړاندې پردي خلک ستاسو ځمکې نیسي او هرڅه ورانوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah1_verse_7.mp3', '', 1761754199, 1761754199),
(45061, 'Isaiah 1:8', 'Isaiah', 1, 8, 'اورشلیم لکه د انګورو په باغ کې د جونګړې او د بادرنګو په پټي کې د څپرې په شان یوازې پاتې دی او کلابند شوی ښار دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah1_verse_8.mp3', '', 1761754199, 1761754199),
(45062, 'Isaiah 1:9', 'Isaiah', 1, 9, 'که چېرې مطلق قادر څښتن ځینې خلک ژوندي نه وای پریښي، نو اورشلیم به د سدوم او عمورې په شان بیخي تباه شوی وای.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah1_verse_9.mp3', '', 1761754199, 1761754199),
(45063, 'Isaiah 1:10', 'Isaiah', 1, 10, 'ای اورشلیمه! ستا حکمرانان او خلک لکه د سدوم او عمورې په شان دي. څه چې څښتن تاسو ته وایي، هغه ته غوږ ونیسئ او زمونږ د خدای تعلیم ته پاملرنه وکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah1_verse_10.mp3', '', 1761754199, 1761754199),
(45064, 'Isaiah 1:11', 'Isaiah', 1, 11, 'څښتن وایي: «ولې زما دپاره دومره قربانۍ؟ کوم پسونه چې تاسو یې ماته د سوځېدونکې قربانۍ په توګه وړاندې کوئ او د ډېرو چاغو حیواناتو وازګه چې ماته نذرانه کوئ بېزاره شوی یم. د غویانو، وریو او وزانو د وینو څخه هم خوشحاله نه یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah1_verse_11.mp3', '', 1761754199, 1761754199),
(45065, 'Isaiah 1:12', 'Isaiah', 1, 12, 'تاسو نه چا دا غوښتي دي چې کله تاسو ماته د عبادت دپاره راځئ نو دا شیان درسره راوړئ؟ ستاسو نه چا دا غوښتنه کړې ده چې راشئ او زما د عبادت ځای تر پښو لاندې کړئ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah1_verse_12.mp3', '', 1761754199, 1761754199),
(45066, 'Isaiah 1:13', 'Isaiah', 1, 13, 'نورې دا بې ګټې نذرانې ماته مه راوړئ. ستاسو د خوشبویۍ د سوځولو د بوی نه کرکه لرم. زه ستاسو د نوې میاشتې اخترونه، ستاسو د سبت ورځې او ستاسو دیني غونډې نه شم زغملی، دا ټول د ګناهونو له امله فاسدې شوې دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah1_verse_13.mp3', '', 1761754199, 1761754199),
(45067, 'Isaiah 1:14', 'Isaiah', 1, 14, 'زه ستاسو د نوې میاشتې د اخترونو او سپېڅلو ورځو څخه کرکه کوم، د دې بار له زغملو څخه ستړی شوی یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah1_verse_14.mp3', '', 1761754199, 1761754199),
(45068, 'Isaiah 1:15', 'Isaiah', 1, 15, 'کله چې تاسو د دعا دپاره لاسونه پورته کړئ، زه به تاسو ته ونه ګورم. تاسو چې هرڅومره دعاګانې وکړئ زه یې نه قبلوم، ځکه چې ستاسو لاسونه په وینو ککړ دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah1_verse_15.mp3', '', 1761754199, 1761754199),
(45069, 'Isaiah 1:16', 'Isaiah', 1, 16, 'خپل ځانونه ووینځئ او پاک شئ. خپل ټول بد کارونه چې زما په وړاندې یې کوئ، هغه پرېږدئ. نور یې مه کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah1_verse_16.mp3', '', 1761754199, 1761754199),
(45070, 'Isaiah 1:17', 'Isaiah', 1, 17, 'نېک کارونه زده کړئ. د انصاف په لټه کې اوسئ، د مظلومانو سره مرسته وکړئ، یتیمانو ته خپل حق ورکړئ او د کونډو د حقونو څخه دفاع وکړئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah1_verse_17.mp3', '', 1761754199, 1761754199),
(45071, 'Isaiah 1:18', 'Isaiah', 1, 18, 'څښتن وایي: «اوس راځئ چې دا موضوع حل کړو. ستاسو ګناهونه د وینې د رنګ په شان دي، خو زه به تاسو داسې ووینځم چې د واورې په شان سپین او د وړیو په شان پاک شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah1_verse_18.mp3', '', 1761754199, 1761754199),
(45072, 'Isaiah 1:19', 'Isaiah', 1, 19, 'که چېرې تاسو غواړئ چې زما اطاعت وکړئ، نو تاسې به د ځمکې ثمره وخورئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah1_verse_19.mp3', '', 1761754199, 1761754199),
(45073, 'Isaiah 1:20', 'Isaiah', 1, 20, 'خو که تاسو انکار او سرغړونه وکړئ، نو په توره به ووژل شئ.» څښتن په خپله داسې ویلي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah1_verse_20.mp3', '', 1761754199, 1761754199),
(45074, 'Isaiah 1:21', 'Isaiah', 1, 21, 'هغه ښار چې یو وخت وفادار ؤ، ولې اوس د بدلمنې ښځې په شان شوی دی؟ دا ښار چې یو وخت د عدالت او نېکۍ څخه ډک ؤ، خو اوس یوازې قاتلان په کې اوسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah1_verse_21.mp3', '', 1761754199, 1761754199),
(45075, 'Isaiah 1:22', 'Isaiah', 1, 22, 'ای اورشلیمه، ته یو وخت د سپینو زرو په شان وې خو اوس د یو بې ارزښته فلز په شان یې. ته د ډېرو ښو انګورو شرابو په شان وې، خو اوس په شرابو کې اوبه ګډې شوې دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah1_verse_22.mp3', '', 1761754199, 1761754199),
(45076, 'Isaiah 1:23', 'Isaiah', 1, 23, 'ستاسو مشران یاغیان او د غلو ملګري دي، هغوی تل سوغاتونه او رشوتونه اخلي. هغوی هېڅکله په محکمو کې د یتیمانو څخه دفاع نه کوي او کله چې کونډې خپلې دعوې وړاندې کوي هغوی ورته غوږ نه نیسي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah1_verse_23.mp3', '', 1761754199, 1761754199),
(45077, 'Isaiah 1:24', 'Isaiah', 1, 24, 'نو اوس مطلق قادر څښتن، د اسراییلو قوي خدای داسې وایي: «زه به خپل دښمنان په خپل غضب اخته کړم او د هغوی نه به خپل بدل واخلم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah1_verse_24.mp3', '', 1761754199, 1761754199),
(45078, 'Isaiah 1:25', 'Isaiah', 1, 25, 'زه به ستاسو په وړاندې اقدام وکړم او تاسو به په داش کې داسې پاک کړم لکه څنګه چې فلز چاڼیږي. ستاسو نه به ټوله ناپاکي لېرې کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah1_verse_25.mp3', '', 1761754199, 1761754199),
(45079, 'Isaiah 1:26', 'Isaiah', 1, 26, 'زه به تاسو ته داسې قاضیان او مشاوران درکړم لکه څنګه چې په پیل کې مو لرل. بیا به اورشلیم د نېکۍ او وفادارۍ د ښار په نوم یاد شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah1_verse_26.mp3', '', 1761754199, 1761754199),
(45080, 'Isaiah 1:27', 'Isaiah', 1, 27, 'څرنګه چې د اورشلیم خلک یوځل بیا انصاف وکړي او توبه وباسي، نو وبه ژغورل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah1_verse_27.mp3', '', 1761754199, 1761754199),
(45081, 'Isaiah 1:28', 'Isaiah', 1, 28, 'خو څوک چې د څښتن په وړاندې سرغړونه او ګناه کوي هغه به تباه شي. هرڅوک چې څښتن پرېږدي، نو هغه به ووژل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah1_verse_28.mp3', '', 1761754199, 1761754199),
(45082, 'Isaiah 1:29', 'Isaiah', 1, 29, 'تاسو به پښېمانه شئ چې د څېړۍ د ونو لاندې مو د عبادت څخه خوند واخیست او وبه شرمېږئ چې په غوره شویو باغونو کې مو عبادت وکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah1_verse_29.mp3', '', 1761754199, 1761754199),
(45083, 'Isaiah 1:30', 'Isaiah', 1, 30, 'تاسې به لکه د بې پاڼو او د وچو څېړیو ونو او بې اوبو باغونو په شان له منځه ځئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah1_verse_30.mp3', '', 1761754199, 1761754199),
(45084, 'Isaiah 1:31', 'Isaiah', 1, 31, 'زورور خلک به د خپلو بدو کړنو په خاطر لکه پنبه چې د اور په لمبه کې سوځي، له منځه لاړ شي. هېڅوک به دا توان ونه لري چې هغوی د دې اور څخه وژغوري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah1_verse_31.mp3', '', 1761754199, 1761754199),
(45085, 'Job 7:1', 'Job', 7, 1, 'بنى آدم په دُنيا کښې سخت محنت نۀ کوى څۀ، او د هغوئ ژوند د مزدور په شان نۀ دے څۀ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job7_verse_1.mp3', '', 1761754199, 1761754199),
(45086, 'Job 7:2', 'Job', 7, 2, 'لکه چې غلامان د سورى په ارمان وى، او لکه مزدوران د خپلې تنخواه په طمع وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job7_verse_2.mp3', '', 1761754199, 1761754199),
(45087, 'Job 7:3', 'Job', 7, 3, 'په مياشتو مياشتو زما څۀ مقصد نشته، او د غم شپې ما له راکړے شوې دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job7_verse_3.mp3', '', 1761754199, 1761754199),
(45088, 'Job 7:4', 'Job', 7, 4, 'کله چې زۀ څملم نو وايم چې، زۀ به کله پاڅم؟ خو شپه اوږده وى، او تر سحر پورې په کټ کښې اوړم راوړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job7_verse_4.mp3', '', 1761754199, 1761754199),
(45089, 'Job 7:5', 'Job', 7, 5, 'زما بدن د دانو او چينجو نه ډک دے، زما څرمن سخا شى او بيا وشليږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job7_verse_5.mp3', '', 1761754199, 1761754199),
(45090, 'Job 7:6', 'Job', 7, 6, 'زما عُمر د سيلۍ په شان تېز روان دے، او په نااُميدۍ کښې ختميږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job7_verse_6.mp3', '', 1761754199, 1761754199),
(45091, 'Job 7:7', 'Job', 7, 7, 'ياد ساته چې زما ژوند صرف يوه ساه ده، او زما سترګې به بيا هيڅکله ښۀ ورځ ونۀ ګورى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job7_verse_7.mp3', '', 1761754199, 1761754199),
(45092, 'Job 7:8', 'Job', 7, 8, 'تۀ ما اوس وينې خو بيا به مې ونۀ ګورې، تۀ به ما لټوې، خو زۀ به نۀ يم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job7_verse_8.mp3', '', 1761754199, 1761754199),
(45093, 'Job 7:9', 'Job', 7, 9, 'لکه څنګه چې وريځ کمه شى او فنا شى، نو چې څوک لاندې قبر ته لاړ شى نو هغه ترې نه بيا هيڅکله نۀ شى راختلے،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job7_verse_9.mp3', '', 1761754199, 1761754199),
(45094, 'Job 7:10', 'Job', 7, 10, 'هغوئ بيا واپس خپلو کورونو ته نۀ شى راتلے، او هغوئ به هيڅکله نۀ ښکارى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job7_verse_10.mp3', '', 1761754199, 1761754199),
(45095, 'Job 7:11', 'Job', 7, 11, 'نو په دې وجه زۀ به خپله خولۀ نۀ بندوم، زۀ به د خپل زړۀ د درد اظهار کوم، زما زړۀ د غصې نه تاو کړے دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job7_verse_11.mp3', '', 1761754199, 1761754199),
(45096, 'Job 7:12', 'Job', 7, 12, 'زۀ سمندرى بلا يم څۀ؟ چې ما د نظر لاندې ساتې؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job7_verse_12.mp3', '', 1761754199, 1761754199),
(45097, 'Job 7:13', 'Job', 7, 13, 'زۀ د دې دپاره څملم چې آرام وکړم، د دې دپاره چې د درد نه خلاص شم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job7_verse_13.mp3', '', 1761754199, 1761754199),
(45098, 'Job 7:14', 'Job', 7, 14, 'نو تۀ بيا ما په خوبونو کښې يروې او په تصور کښې مې يروې،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job7_verse_14.mp3', '', 1761754199, 1761754199),
(45099, 'Job 7:15', 'Job', 7, 15, 'نو زما دپاره د ساه بندېدل ښۀ دى، د داسې کړاؤ نه په مرګ خوشحال يم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job7_verse_15.mp3', '', 1761754199, 1761754199),
(45100, 'Job 7:16', 'Job', 7, 16, 'زۀ د خپل ژوند نه نفرت کوم، زۀ به همېشه ژوندے نۀ يم. په دې لنډ تنګ ژوند کښې ما پرېږده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job7_verse_16.mp3', '', 1761754199, 1761754199),
(45101, 'Job 7:17', 'Job', 7, 17, 'بنى آدم څۀ څيز دے، چې تۀ يې دومره خاص ګڼې، چې تۀ هغوئ ته دومره توجو ورکوې،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job7_verse_17.mp3', '', 1761754199, 1761754199),
(45102, 'Job 7:18', 'Job', 7, 18, 'هر سحر يې معائنه کوې، او هر وخت هغوئ معلوموې؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job7_verse_18.mp3', '', 1761754199, 1761754199),
(45103, 'Job 7:19', 'Job', 7, 19, 'تۀ به ما له د يوې لحظې موقع رانۀ کړې چې ساه پکښې واخلم؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job7_verse_19.mp3', '', 1761754199, 1761754199),
(45104, 'Job 7:20', 'Job', 7, 20, 'اے د بنيادمو ليدونکيه، کۀ زۀ ګناه کوم، نو په تا باندې څۀ اثر کوى؟ تا زۀ ولې په نښه کړے يم؟ زۀ په تا باندې بوج جوړ شوے يم څۀ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job7_verse_20.mp3', '', 1761754199, 1761754199),
(45105, 'Job 7:21', 'Job', 7, 21, 'تۀ زما غلطيانې ولې نۀ معاف کوې او زما ګناه ولې نۀ لرې کوې؟ زۀ به ډېر زر په لحد کښې پروت يم، تۀ به ما لټوې، خو زۀ به مړ يم.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job7_verse_21.mp3', '', 1761754199, 1761754199),
(45106, 'Proverbs 30:1', 'Proverbs', 30, 1, 'دا د یاقه د زوی اګور خبرې دي. اګور ایتییل ته پیغام ورکوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs30_verse_1.mp3', '', 1761754199, 1761754199),
(45107, 'Proverbs 30:2', 'Proverbs', 30, 2, 'په حقیقت کې زه د هرچا نه ناپوهه یم او په ما کې د انسان په شان عقل نشته.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs30_verse_2.mp3', '', 1761754199, 1761754199),
(45108, 'Proverbs 30:3', 'Proverbs', 30, 3, 'ما پوهه او حکمت نه دي زده کړي او د سپېڅلي ذات د پېژندلو علم نه لرم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs30_verse_3.mp3', '', 1761754199, 1761754199),
(45109, 'Proverbs 30:4', 'Proverbs', 30, 4, 'څوک اسمان ته پورته شوی او بېرته راښکته شوی دی؟ چا هوا په موټي کې نیولې او اوبه یې په څادر کې اچولي دي؟ او چا دا ټوله ځمکه پیدا کړې ده؟ د هغه نوم څه دی او د زوی نوم یې څه شی دی؟ که ته پوهېږې نو ماته ووایه!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs30_verse_4.mp3', '', 1761754199, 1761754199),
(45110, 'Proverbs 30:5', 'Proverbs', 30, 5, 'د خدای د کلام هره خبره سوچه او د باور وړ ده څوک چې هغه ته پناه وروړي د هغوی دپاره سپر دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs30_verse_5.mp3', '', 1761754199, 1761754199);